import {forecastPurchaseDecision,forecastSummary} from './forecast-model.js?v=20261023-forecast';
import {lineChart,barChart} from './charts.js?v=20261023-timing';
import {escapeHTML as esc,finite,num,pct,signed,normalizeTogether,COLORS} from './model.js';
import {price} from './domestic-model.js';
import {timingDecision,selectTimingProduct,recentSeriesPoints,scenarioCost,monthlyChartPoints} from './timing-model.js?v=20261023-timing';

const won=v=>finite(v)?`${num(Math.round(v),0)}원`:'확인 필요';
const change=v=>finite(v)?pct(v):'표본 부족';
const opts=(rows,v)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(v)?'selected':''}>${esc(label)}</option>`).join('');
const selector=(id,label,rows,v)=>`<label class="t-control" for="${id}"><span>${label}</span><select id="${id}" data-select="${id}">${opts(rows,v)}</select></label>`;
const chips=(action,rows,v)=>`<div class="t-chips" role="group" aria-label="${action==='timingCategory'?'부품 종류':'가격 이력 기간'}">${rows.map(([id,label])=>`<button data-action="${action}" data-value="${id}" class="${String(id)===String(v)?'active':''}" aria-pressed="${String(id)===String(v)}">${label}</button>`).join('')}</div>`;
const metric=(label,value,sub,cls='')=>`<div class="t-metric ${cls}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`;
const table=(headers,rows)=>`<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const download=(file,label)=>`<a class="button" href="./data/downloads/${file}" download>${label} ↓</a>`;
const names={'AMD':'AMD','INTC':'인텔','MU':'마이크론','NVDA':'엔비디아','005930.KS':'삼성전자','000660.KS':'SK하이닉스','ETH-USD':'이더리움'};

export function renderTiming(main,domestic,timing,state,forecast){
 const all=[...domestic.products,...domestic.marketReferences],p=selectTimingProduct(all,state.timingProduct,state.timingCategory);
 state.timingProduct=p.id;state.timingCategory=p.category;
 const h=timing.products.find(x=>x.id===p.id),horizon=Number(state.timingHorizon),observed=timingDecision(p,h,all,{horizon,urgency:state.timingUrgency}),model=forecast?.series.find(s=>s.domesticId===p.id),decision=forecastPurchaseDecision(observed,model,{horizon,urgency:state.timingUrgency});
 const a=decision.evidence,t=a?.trend??{},v=a?.validation??{},peer=decision.peer,weekly=state.timingFrequency==='weekly',longPlan=horizon>=12;
 const rows=weekly?h.weekly:h.monthly;
 const points=weekly?rows.map(r=>({date:r.date,value:r.price})):monthlyChartPoints(rows);
 const costs=[-.05,0,.05].map(x=>({x,value:scenarioCost(peer.current,x)}));
 const peerPriority=x=>x.chip===p.chip?0:p.category==='CPU'&&x.socket===p.socket||p.category==='GPU'&&x.comparisonTier===p.comparisonTier?1:2;
 const bestAlternatives=all.filter(x=>x.id!==p.id&&x.category===p.category&&(p.category!=='RAM'||x.performance.capacity.group===p.performance.capacity.group)).map(x=>({p:x,d:timingDecision(x,timing.products.find(y=>y.id===x.id),all,{horizon,urgency:state.timingUrgency})})).filter(x=>!x.d.peer.thin&&!x.d.peer.flag.outlier).sort((x,y)=>peerPriority(x.p)-peerPriority(y.p)||(x.d.peer.current??Infinity)-(y.d.peer.current??Infinity)).slice(0,3);
 main.innerHTML=`<section class="t-hero"><div><div class="t-kicker">PC 부품 업그레이드 플래너</div><h1>지금 살까,<br class="mobile-break"> 조금 더 기다릴까?</h1><p>제품을 고르면 ${longPlan?'3개월 확률 모형의 검증 결과와':'최근 가격 흐름과'} 다음 구매 행동을 확인할 수 있습니다.</p></div><div class="t-stamp"><i></i><b>2026.10.23 기준</b><span>국내 21개 제품 · 저장 스냅샷</span></div></section>
 <section class="t-picker" aria-label="구매 계획 설정"><div class="t-picker-category"><span class="step-number">1</span><b>어떤 부품인가요?</b>${chips('timingCategory',['CPU','RAM','SSD','GPU'].map(x=>[x,x]),p.category)}</div><div class="t-picker-fields">${selector('timingProduct','제품 선택',all.filter(x=>x.category===p.category).map(x=>[x.id,x.shortName]),p.id)}${selector('timingUrgency','언제 필요한가요?',[['flexible','기다릴 수 있어요'],['immediate','지금 필요해요']],state.timingUrgency)}${selector('timingHorizon','계획 기간',[['4','앞으로 약 1개월'],['8','앞으로 약 2개월'],['12','3개월 이상 · 검증 결과로 판단']],state.timingHorizon)}</div>${horizon===8?'<p class="t-muted">2개월 방향은 미검증입니다. 이 계획의 행동 안내는 최근 4주에 근거합니다.</p>':''}</section>
 <section class="t-decision ${decision.tone}" aria-label="구매 시점 판단"><div class="t-decision-main"><div class="t-decision-label"><span class="step-number">2</span>${longPlan?'예측 검증에 따른 구매 판단':'최근 추세로 정한 다음 행동'} <span class="t-rule-tag">${longPlan?'모형 검증 후 채택 여부 결정':'단기 관측 규칙 · 확률 예측 아님'}</span></div><h2>${decision.title}</h2><p>${decision.reason}</p><div class="t-next"><b>다음 행동</b><span>${decision.next}</span></div></div><div class="t-quote"><span>현재 비교 견적</span><strong>${won(peer.current)}</strong><small>${peer.current?'일반몰 3곳 · 배송 포함 중앙값':'배송 확인 3몰 견적 미확보'}<br>${p.quote.displayedSellerCount}개 표시 판매처 · ${domestic.asOf}</small><a href="${esc(p.quote.sourceUrl)}" target="_blank" rel="noopener noreferrer">판매 페이지에서 확인 ↗</a></div></section>
 ${longPlan?`<section class="t-long-trends panel"><div><b>장기 흐름도 함께 확인합니다</b><span>완료 월 ${a.longTrend.asOf} 기준 · 10월 부분월 제외</span></div>${metric('최근 3개월',change(a.longTrend.threeMonth),'같은 월간 버킷의 비교')}${metric('최근 6개월',change(a.longTrend.sixMonth),'관측 변화 · 미래 예측과 구분')}${metric('다음 재점검','약 4주 뒤','자동 알림·수집 없음')}</section>`:''}<div class="t-evidence-grid"><section class="panel t-price-panel"><div class="panel-head"><div><div class="t-kicker">판단 근거</div><h2>${esc(p.shortName)} 가격 흐름</h2></div>${chips('timingFrequency',[['weekly','최근 12주'],['monthly','장기 월간']],state.timingFrequency)}</div><div class="t-trends">${metric('최근 1주',change(t.oneWeek),'직전 관측 대비',t.oneWeek<0?'fall':'')}${metric('최근 4주',change(t.fourWeek),'정확히 28일 전 대비',t.fourWeek<0?'fall':'')}${metric('실제 관측',weekly?`${a.weeklyN} / ${a.weeklyTotal}주`:`${a.monthlyN}개월` ,weekly?'2026.08.04–10.20':`완료 월만 · 부분월 ${a.monthlyPartialN}개 별도`)}</div><div id="timing-chart" class="chart-zone"></div><div class="panel-foot">${weekly?'화요일 원문 관측값':'원문 월간 버킷 · 월평균·월말가로 확인되지 않음 · 2026.10 부분월 포함(최종 점)'} · 배송·할인 포함 기준 미확인.<br>현재 견적은 배송 포함 3몰 중앙값으로 기준이 달라 이 선에 이어 붙이지 않았습니다.</div></section>
 <aside class="t-outlook panel">${longPlan?forecastSummary(model):`<div class="t-kicker">${longPlan?'3개월 이상 계획':`앞으로 ${horizon}주`}</div><h2>얼마나 더 오르거나 내릴까?</h2><div class="t-probability"><strong>상승·하락 확률 산출 보류</strong><p>검증된 확률모형이 없습니다. 현재 판단은 ${longPlan?'완료 월의 3·6개월과 최근 4주':'최근 4주'} 추세를 이용한 행동 규칙입니다.</p></div><div class="t-eval"><div><span>월간 ${v.horizonMonths}개월 뒤 예측 시험</span><b>${v.n??0}회 <small>비중첩 ${v.independentN??0}회</small></b></div><div><span>단순 추세 모형 평균 오차</span><b>${finite(v.mae)?`${num(v.mae*100,1)}%p`:'표본 없음'}</b></div><div><span>가격 그대로 예측한 경우</span><b>${finite(v.naiveMae)?`${num(v.naiveMae*100,1)}%p`:'표본 없음'}</b></div></div><p class="t-eval-result">${finite(v.skill)?v.skill>0?`유지 모형보다 평균 오차가 ${num(v.skill*100,1)}% 작았지만, 짧은 검증만으로 미래 확률을 보장할 수 없습니다.`:'단순 추세 모형이 ‘현재 가격 유지’보다 낫지 않았습니다. 이 예측을 구매 추천에 쓰지 않습니다.':'방향 예측을 평가할 표본도 부족합니다.'}</p><a href="#quality" class="t-inline-link">검증 방법과 표본 보기 →</a>`}</aside></div>
 <section class="t-planning"><div class="t-section-title"><div><span class="step-number">3</span><h2>구매 예산과 기다릴 때의 비용을 확인하세요</h2></div><p>구매 판단과 함께 예산 상한을 정하는 단계입니다.</p></div><div class="t-plan-grid"><article class="panel t-plan-card"><span class="t-kicker">성능 대비 비교 기준가</span><h3>${peer.cap?won(peer.cap):'유효한 비교군 부족'}</h3><p>${peer.cap?'현재 동급 제품의 가격·성능으로 계산한 동률 가격 중앙값입니다. 미래 가격 예측이나 보장된 적정가는 아닙니다.':'같은 기준의 성능·가격 비교가 부족해 기준가를 표시하지 않습니다.'}</p><small>CPU: 제출 실측 집계 · GPU: 23종 게임 · RAM/SSD: 사양 비교</small><button class="button" data-action="inspectProduct" data-value="${p.id}">성능·호환·산정 근거 보기 →</button></article><article class="panel t-plan-card"><span class="t-kicker">내 예산에 미치는 영향</span><h3>가격이 5% 움직인다면</h3><div class="t-scenarios">${costs.map(c=>`<div><span>${c.x<0?'5% 하락':c.x>0?'5% 상승':'현재 견적'}</span><b>${won(c.value)}</b></div>`).join('')}</div><p>현재 견적에 ±5%를 적용한 비용 예시입니다. 발생 확률·예상 가격 범위가 아닙니다.</p></article></div></section>
 <section class="t-alternatives"><div class="t-section-title"><div><h2>같은 부품의 다른 선택지도 확인하세요</h2></div><p>같은 칩·호환 그룹 우선, 그룹 안에서 가격순 · 최종 호환은 확인 필요</p></div><div class="t-alternative-grid">${bestAlternatives.map(x=>`<button class="t-alternative" data-action="timingProduct" data-value="${x.p.id}"><span>${esc(x.p.shortName)}</span><strong>${won(x.d.peer.current)}</strong><small>최근 4주 ${change(x.d.evidence?.trend.fourWeek)} <b>판단 보기 →</b></small></button>`).join('')}</div></section>
 <details class="t-method"><summary>이 구매 판단은 어떻게 만들었나요?</summary><div>${longPlan?`<p>국내 동일 가격 정의의 21개 제품 월간 패널에 L2 다항 로지스틱 회귀를 학습했습니다. 각 예측 분기 전에 정답의 목표 월까지 종료한 자료만 사용하고 부분월·미관측 목표는 제외합니다. 과거 발생 빈도 기준과 확률 오차를 비교했습니다.</p><p>현재 ${model?.evaluation.n??0}회 검증과 비중첩 ${model?.evaluation.nonoverlapN??0}개 시간 구간만으로는 추천 사용 기준을 통과하지 못했습니다. 단기 추세 규칙을 3개월 예측으로 대체 표시하지 않습니다. 완료 월 버킷 예측은 현재 3몰 중앙값의 미래 견적도 아닙니다.</p><div class="download-list"><a class="button" href="./data/downloads/forecast_protocol.md">고정 검증 규약 ↓</a><a class="button" href="./data/downloads/forecast_predictions.csv" download>실제 예측·정답 CSV ↓</a></div>`:`<p>최근 4주 3% 초과 상승 + 마지막 주 비하락 + 최근 4개 구간 중 2주 이상 상승이면, 곧 필요한 구매를 검토합니다. 4주 3% 초과 하락 + 마지막 주 상승 1% 이하면 대기를 검토합니다. 혼재하면 필요 시점을 우선합니다. 3%·1%는 사용자 행동을 위한 정책 기준이며 최적화된 예측 기준이 아닙니다.</p><p>판매처 3곳 미만·동일칩 호가 주의·오래된 데이터·현재 견적과 이력 차이 15% 초과는 먼저 재확인합니다. 주가 상관·제조사 전망을 SKU 상승 확률로 변환하지 않습니다. ${longPlan?'3개월 이상 계획에서는 완료 월 3·6개월이 각각 5% 넘게 상승하고 위 주간 상승 조건도 맞으면 앞당김을 검토합니다. 완료 월 3개월과 4주가 함께 하락하면 대기를 검토하며, 신호 혼재·장기 자료 부족은 한 달 뒤 재점검합니다. 기간 전체의 방향·확률은 미검증입니다.':horizon===8?'2개월 행동은 최근 4주에 근거하며 기간 전체 방향은 미검증입니다.':''}</p><p>주간 이력은 12점으로 ${horizon}주 간격 변화 ${a.historyComparisons.n}건(중첩), 비중첩 ${a.historyComparisons.independentN}건입니다. 월간 시험은 정확히 ${v.horizonMonths}개 달 뒤를 평가하므로 ${horizon}주 예측의 검증으로 볼 수 없습니다. 월간 버킷은 현재 조회 시점의 자료여서 당시 정보 상태를 완전히 재현하지 못합니다.</p><div class="download-list">${download('domestic_timing_history.csv','최근 가격 이력')}${download('domestic_timing_validation.csv','예측 시험 CSV')}<a class="button" href="./data/timing.json" download>검증 결과 JSON ↓</a></div>`}</div></details>`;
 lineChart(main.querySelector('#timing-chart'),[{name:weekly?'원문 주간 가격':'원문 월간 버킷',color:'#197b68',points}],{title:`${p.shortName} ${weekly?'주간':'월간'} 가격 이력`,unit:'원 · 원문 minPrice',showPoints:true,monthly:!weekly,monthlyLabel:'원문 버킷',height:310});
}

export function archiveNav(main,page){
 const html=`<div class="t-archive-banner"><div><b>과거 사례 연구 · 2020–2022</b><p>채굴 붐과 당시 주가 관계를 살펴보는 자료입니다. 현재 구매 타이밍은 별도 화면에서 확인하세요.</p></div><a class="button" href="#domestic">현재 구매 판단 →</a></div><div class="t-archive-nav">${[['mining','채굴 붐'],['prices','당시 가격 추이'],['correlations','당시 주가 상관']].map(([id,label])=>`<a href="#${id}" ${page===id?'aria-current="page"':''}>${label}</a>`).join('')}</div>`;
 main.insertAdjacentHTML('afterbegin',html);
}

export function renderRecent(main,recent,state){
 const parts=recent.series.filter(x=>x.kind==='part'),markets=recent.series.filter(x=>x.kind!=='part');
 const p=parts.find(x=>x.id===state.recentPart)??parts[0],s=markets.find(x=>x.id===state.recentMarket)??markets[0],year=state.recentYear;
 const pPoints=recentSeriesPoints(p,year),sPoints=recentSeriesPoints(s,year);
 const indexed=normalizeTogether([{name:p.name,color:COLORS[0],points:pPoints},{name:names[s.id]??s.name,color:COLORS[1],points:sPoints}]);
 const rows=recent.correlations.filter(x=>x.partId===p.id&&x.marketId===s.id&&x.mode==='returns'),selected=rows.find(x=>x.lag_weeks===Number(state.recentLag));
 const pValid=pPoints.filter(x=>finite(x.value)),sValid=sPoints.filter(x=>finite(x.value));
 main.innerHTML=`<section class="t-hero"><div><div class="t-kicker">최근 시장 · 2023–2026</div><h1>최근 가격과 주가를 함께 읽기</h1><p>해외 CPU·SSD 2개 SKU의 확보 이력을 2026년까지 확장했습니다.</p></div><div class="t-stamp"><b>시장 일별 최신 2026.10.22</b><span>완료 주 비교는 2026.10.16까지</span></div></section><div class="t-picker t-recent-picker">${selector('recentPart','해외 가격',parts.map(x=>[x.id,x.name]),p.id)}${selector('recentMarket','비교 시장',markets.map(x=>[x.id,names[x.id]??x.name]),s.id)}${selector('recentYear','그래프 기간',[['all','2023–2026 전체'],['2026','2026년'],['2025','2025년'],['2024','2024년'],['2023','2023년']],year)}</div><div class="t-notice">미국 Amazon의 구형 SKU 호가입니다. 현재 국내 동급 제품의 구매 신호로 대체하지 않습니다. 최신 일별 시세와 주별 분석의 마지막 날짜도 다릅니다.</div><section class="panel"><div class="panel-head"><h2>공통 관측일 = 100 · 통화가 다른 계열 비교</h2><span class="pill">주간 · 이월·보간 없음</span></div><div class="t-trends">${metric('부품 가격 관측',`${pValid.length} / ${pPoints.length}주`,pValid.length?`마지막 실제 관측 ${pValid.at(-1).quoteDate??pValid.at(-1).date}`:'미관측')}${metric('시장 가격 관측',`${sValid.length} / ${sPoints.length}주`,s.priceBasis==='adjustedClose'?'배당·분할 수정주가':'ETH 종가 · 채굴 수익 아님')}${metric('함께 비교하는 기준일',indexed[0]?.baseDate??'없음','두 계열이 동시에 관측된 첫 주')}</div><div id="recent-chart" class="chart-zone"></div><div class="legend"><span><i style="background:${COLORS[0]}"></i>${esc(p.name)}</span><span><i style="background:${COLORS[1]}"></i>${esc(names[s.id]??s.name)}</span></div><div class="panel-foot">토~금 중 마지막 유효 관측 · ${p.currency} 부품과 ${s.currency} 시장을 지수화. 회색 공백은 실제 미관측으로 연결하지 않습니다.</div></section><section class="panel section-block"><div class="panel-head"><div><h2>주별 변화율의 시차 상관</h2><p class="panel-subtitle">2023–2026 전체 구간 고정 · 위 그래프 연도 선택과 별도 · ${rows.length}개 시차 탐색</p></div></div><div class="panel-inner"><div class="t-correlation"><div><strong>${signed(selected?.pearson)}</strong><span>실제 관측 쌍 n = ${selected?.n??0}</span></div>${selector('recentLag','시장 변화가 부품보다',[...Array(17)].map((_,i)=>[String(i-8),i===8?'같은 주':i>8?`${i-8}주 앞설 때`:`${8-i}주 뒤일 때`]),state.recentLag)}</div><div id="recent-lags"></div><p class="t-muted">바로 전 주가 없으면 변화율을 만들지 않습니다. +시차는 시장 t주와 부품 t+시차주입니다. 여러 시차 중 가장 큰 값을 고르는 것은 예측 성능 검증이 아닙니다. 통계적 유의성·인과·미래 예측력은 주장하지 않습니다.</p></div></section><details class="t-method"><summary>최근 데이터의 실제 표본 수·출처·다운로드</summary><div>${table(['자료','관측 주 / 달력 주','인접 주 변화율','마지막 유효 주','일별 시장 관측','원문'],recent.series.map(x=>[esc(names[x.id]??x.name),`${x.coverage.observed} / ${x.coverage.total}`,x.coverage.returns,x.coverage.last??'—',x.dailyCoverage?`${x.dailyCoverage.n}일 · ${x.dailyCoverage.last}`:'해당 없음',`<a href="${esc(x.sourceUrl)}" target="_blank" rel="noopener noreferrer">출처 ↗</a>`]))}<p>${recent.limitations.map(x=>esc(x)).join('<br>')}</p><div class="download-list"><a class="button" href="./data/recent.json" download>최근 분석 전체 JSON ↓</a>${download('recent_parts_weekly.csv','해외 가격 CSV')}${download('recent_markets_weekly.csv','최근 시장 CSV')}${download('recent_correlations.csv','최근 상관 CSV')}</div></div></details>`;
 lineChart(main.querySelector('#recent-chart'),indexed,{title:'2023–2026 부품과 시장 가격 지수',unit:'공통 첫 관측 주 = 100',start:year==='all'?recent.start:year+'-01-01',end:year==='all'?recent.weeklyEnd:year==='2026'?recent.weeklyEnd:year+'-12-31',height:350});
 barChart(main.querySelector('#recent-lags'),rows,{title:'최근 가격·시장 변화율 시차 상관',selected:Number(state.recentLag)});
}

export function renderDataHub(main,domestic,timing,recent,forecast){
 const weekly=timing.products.reduce((n,p)=>n+p.weekly.filter(x=>finite(x.price)).length,0),complete=timing.products.reduce((n,p)=>n+p.monthly.filter(x=>!x.partial&&finite(x.price)).length,0);
 main.innerHTML=`<section class="t-hero"><div><div class="t-kicker">데이터와 판단의 근거</div><h1>어디까지 알고, 무엇은 모르는가</h1><p>최근 구매 판단과 과거 사례 연구를 분리했습니다.</p></div></section><section class="panel"><div class="panel-head"><h2>자료 범위 · 2026년까지 갱신</h2></div><div class="panel-inner">${table(['용도','기간','실제 확보 범위','한계'],[['현재 견적',domestic.asOf,'국내 21개 SKU · 3몰 중앙값 별도','실제 재고·결제 성공·독립 판매자 미검증'],['최근 국내 추세','2026.08.04–10.20',`${weekly}개 주간 점 · 제품당 12개`,'확률 예측에 짧음 · 화요일 값'],['국내 장기 맥락','최대 2024.12–2026.10',`${complete}개 완료 월 · 10월 부분월 별도`,'제품마다 시작월 다름 · 월간 집계 정의 미확인'],['최근 해외·시장','2023–2026','해외 SKU 2개 + 주가 6종 + ETH','주별 비교 10.16까지 · 일별 시장 10.22까지'],['채굴 붐 사례','2020–2022','GPU 3종 + 당시 CPU/SSD·주가·ETH','2020 GPU 수치 미확보 · 실제 채굴 순익 미확보']])}</div></section><section class="panel section-block"><div class="panel-head"><h2>기존 추세 연장 기준의 오차 · 새 확률 모형과 별도</h2></div><div class="panel-inner"><p>완료 월만 사용해 직전 3개월의 월간 변화율 중앙값으로 1·2·3개월 뒤를 시험했습니다. 아래 표는 기존 단순 기준의 3개월 뒤 결과입니다. 실제 학습한 확률 모형의 결과는 위 새 검증 화면에서 확인하세요. 각 과거 시점의 뒤쪽 값은 입력에서 제외하고, 가격이 그대로 유지된다는 단순 기준과 평균 절대오차를 비교했습니다. 월간 1개월은 정확히 4주와 같지 않습니다.</p><p class="t-muted">이 실험은 현재 조회한 월간 버킷의 순차 검증입니다. 당시 공개됐던 빈티지 자료를 확보한 검증은 아닙니다. 방향 확률의 보정도 검증하지 않았습니다. 비중첩 검증 30개라는 사전 검토 기준 역시 충분성을 보장하지 않습니다. 비중첩은 평가 대상 기간이 겹치지 않는다는 뜻이며 통계적 독립성을 보장하지 않습니다.</p>${table(['제품','다음 3개월 시험','비중첩 시험','추세 모형 오차','가격 유지 오차','확률'],timing.products.map(p=>{const a=p.analysis['12'].validation,d=[...domestic.products,...domestic.marketReferences].find(d=>d.id===p.id);return [esc(d.shortName),a.n,a.independentN,finite(a.mae)?`${num(a.mae*100,1)}%p`:'—',finite(a.naiveMae)?`${num(a.naiveMae*100,1)}%p`:'—','보류'];}))}</div></section><details class="t-method"><summary>구매 행동 규칙·가격 정의·원문</summary><div><p>${timing.limitations.map(esc).join('<br>')}</p><p>원문 이력은 minPrice입니다. 현재 견적은 배송 확인 일반몰 3곳의 중앙값으로 성격이 다릅니다. 같은 정의로 연결한 시계열이나 실거래량을 만들지 않았습니다. CPU·GPU 성능은 ‘성능·가격 비교’에서 개별 출처와 실측 조건을 확인할 수 있습니다.</p><div class="download-list"><a class="button" href="./data/timing.json" download>최근 국내 근거 JSON ↓</a><a class="button" href="./data/recent.json" download>2023–2026 시장 JSON ↓</a>${download('domestic_timing_history.csv','국내 이력 CSV')}${download('domestic_timing_validation.csv','예측 시험 CSV')}</div><div class="source-list">${timing.methodSources.map(s=>`<div class="source-item"><strong>${esc(s.name)}</strong><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">원문 ↗</a></div>`).join('')}</div></div></details><div class="t-notice">현재는 저장 스냅샷입니다. 사이트를 다시 열어도 가격이 자동 수집되거나 가격 알림이 발송되지는 않습니다. <a href="#mining">2020–2022 과거 사례 →</a> · <a href="#archive-quality">과거 분석의 상세 검증·보고서 →</a></div>`;
 if(forecast){const newer=forecast.series.filter(s=>!s.id.startsWith('KR_')&&!s.id.startsWith('US_')&&!s.id.startsWith('IN_'));
 main.querySelector('.t-hero').insertAdjacentHTML('afterend',`<section class="panel section-block"><div class="panel-head"><h2>새 3개월 확률 모형 · 실제 학습과 검증</h2><a class="button" href="#forecast">예측 검증 화면 →</a></div><div class="panel-inner"><p>국내 21개 월간 계열과 해외 ${forecast.series.length-21}개 주간 계열을 별도로 다룹니다. 신규 해외 ${newer.length}개 원문 ${newer.reduce((n,s)=>n+s.coverage.rawN,0)}건, 국내 과거 스냅샷 ${forecast.totals.archiveQuotes+forecast.totals.quarantinedArchives}건을 추가 확보했습니다(가격 기준 교차 확인 ${forecast.totals.archiveQuotes}건·충돌 격리 ${forecast.totals.quarantinedArchives}건). 국내 아카이브는 가격 기준이 달라 모형에서 제외했습니다.</p><p>미래 구간 예측·정답 ${forecast.totals.backtests}건을 보존했습니다. 같은 시간 구간을 공유하는 여러 제품과 중첩 예측을 독립 표본으로 합산하지 않습니다. 구매 추천 기준을 통과한 계열은 ${forecast.totals.passed}개입니다.</p><div class="download-list"><a class="button" href="./data/downloads/forecast_protocol.md">사전 고정 검증 규약 ↓</a><a class="button" href="./data/downloads/forecast_metrics.csv" download>모든 제품의 실제 점수 ↓</a><a class="button" href="./data/downloads/excluded_observations.csv" download>제외한 관측·사유 ↓</a></div></div></section>`);}

}
